import pandas as pd
import numpy as np
import os
from pathlib import Path

def load_ensemble_results(base_dir="ensemble_results"):
    """Load all ensemble results from dataset directories generated by ensemble_simple.py"""
    results = {}
    summary_results = {}
    
    # Find all dataset directories in ensemble_results/
    ensemble_dir = Path(base_dir)
    if not ensemble_dir.exists():
        print(f" Directory {base_dir} not found. Make sure ensemble_simple.py has been run.")
        return results, summary_results
    
    for dataset_dir in ensemble_dir.iterdir():
        if dataset_dir.is_dir():
            # Look for {dataset}_all_results.csv and {dataset}_summary.csv
            all_results_path = dataset_dir / f"{dataset_dir.name}_all_results.csv"
            summary_path = dataset_dir / f"{dataset_dir.name}_summary.csv"
            
            if all_results_path.exists():
                try:
                    df = pd.read_csv(all_results_path, sep=';', decimal=',')
                    results[dataset_dir.name] = df
                    print(f" Loaded {dataset_dir.name}_all_results.csv: {len(df)} rows")
                except Exception as e:
                    print(f" Error loading {dataset_dir.name}_all_results.csv: {e}")
            
            if summary_path.exists():
                try:
                    df_summary = pd.read_csv(summary_path, sep=';', decimal=',')
                    summary_results[dataset_dir.name] = df_summary
                    print(f" Loaded {dataset_dir.name}_summary.csv: {len(df_summary)} rows")
                except Exception as e:
                    print(f" Error loading {dataset_dir.name}_summary.csv: {e}")
    
    return results, summary_results

def analyze_improvements(results_dict):
    """Analyze ensemble improvements over individual models using real experimental data"""
    improvements = []
    
    for dataset_name, df in results_dict.items():
        print(f"\n Analyzing {dataset_name}...")
        
        # Group by seed to analyze improvements per seed
        for seed in df['Seed'].unique():
            seed_data = df[df['Seed'] == seed].copy()
            
            # Separate individual and ensemble results for this seed
            individual = seed_data[seed_data['Type'] == 'Individual'].copy()
            ensemble = seed_data[seed_data['Type'] == 'Ensemble'].copy()
            
            if len(individual) == 0 or len(ensemble) == 0:
                print(f"  Skipping {dataset_name} seed {seed}: missing individual or ensemble data")
                continue
            
            # Get best individual performance for this seed
            if 'Image_AP_AUPR' in individual.columns:
                best_individual = individual.loc[individual['Image_AP_AUPR'].idxmax()]
            else:
                print(f"  No Image_AP_AUPR column in individual data for {dataset_name}")
                continue
            
            # Analyze each ensemble method for this seed
            for _, ens_row in ensemble.iterrows():
                method = ens_row.get('Method', 'unknown')
                model1 = ens_row.get('Model1', '')
                model2 = ens_row.get('Model2', '')
                
                # Calculate improvements using available metrics
                auroc_improvement = ens_row.get('image_AUROC', 0) - best_individual.get('image_AUROC', 0)
                ap_improvement = ens_row.get('Image_AP_AUPR', 0) - best_individual.get('Image_AP_AUPR', 0)
                spro_improvement = ens_row.get('sPRO@0.05', 0) - best_individual.get('sPRO@0.05', 0)
                auspro_improvement = ens_row.get('AUsPRO@0.05', 0) - best_individual.get('AUsPRO@0.05', 0)
                
                improvements.append({
                    'Dataset': dataset_name,
                    'Seed': seed,
                    'Method': method,
                    'Model1': model1,
                    'Model2': model2,
                    'Best_Individual_Model': best_individual.get('Model', 'unknown'),
                    'Individual_AUROC': best_individual.get('image_AUROC', 0),
                    'Ensemble_AUROC': ens_row.get('image_AUROC', 0),
                    'AUROC_Improvement': auroc_improvement,
                    'Individual_AP': best_individual.get('Image_AP_AUPR', 0),
                    'Ensemble_AP': ens_row.get('Image_AP_AUPR', 0),
                    'AP_Improvement': ap_improvement,
                    'Individual_sPRO': best_individual.get('sPRO@0.05', 0),
                    'Ensemble_sPRO': ens_row.get('sPRO@0.05', 0),
                    'sPRO_Improvement': spro_improvement,
                    'Individual_AUsPRO': best_individual.get('AUsPRO@0.05', 0),
                    'Ensemble_AUsPRO': ens_row.get('AUsPRO@0.05', 0),
                    'AUsPRO_Improvement': auspro_improvement,
                    'TPR@TNR0.95': ens_row.get('TPR@TNR0.95', 0),
                    'TPR@TNR0.99': ens_row.get('TPR@TNR0.99', 0),
                    'TPR@TNR0.90': ens_row.get('TPR@TNR0.90', 0),
                })
    
    return pd.DataFrame(improvements)

def generate_paper_tables(improvements_df, summary_results):
    """Generate publication-ready tables using both seed-level and summary data"""
    
    print("\n" + "="*80)
    print(" ENSEMBLE ANALYSIS FOR ACADEMIC PUBLICATION")
    print("="*80)
    
    # Table 1: Significant Improvements (by dataset and method)
    print("\n TABLE 1: ENSEMBLE IMPROVEMENTS ANALYSIS")
    print("-"*80)
    
    # Group by dataset and method to get average improvements across seeds
    improvement_summary = improvements_df.groupby(['Dataset', 'Method', 'Model1', 'Model2']).agg({
        'AUROC_Improvement': ['mean', 'std', 'count'],
        'AP_Improvement': ['mean', 'std'],
        'sPRO_Improvement': ['mean', 'std'],
        'AUsPRO_Improvement': ['mean', 'std'],
        'Best_Individual_Model': 'first'
    }).round(4)
    
    improvement_summary.columns = ['AUROC_Improv_Mean', 'AUROC_Improv_Std', 'N_Seeds',
                                  'AP_Improv_Mean', 'AP_Improv_Std',
                                  'sPRO_Improv_Mean', 'sPRO_Improv_Std',
                                  'AUsPRO_Improv_Mean', 'AUsPRO_Improv_Std',
                                  'Best_Individual']
    improvement_summary = improvement_summary.reset_index()
    
    # Filter significant improvements
    significant_improvements = improvement_summary[
        (improvement_summary['AUROC_Improv_Mean'] > 0.01) | 
        (improvement_summary['AP_Improv_Mean'] > 0.01) |
        (improvement_summary['sPRO_Improv_Mean'] > 0.05)
    ].copy()
    
    if len(significant_improvements) > 0:
        print(f"Found {len(significant_improvements)} significant ensemble improvements:")
        print(significant_improvements.to_string(index=False))
        
        # Save for LaTeX
        significant_improvements.to_csv('paper_table1_significant_improvements.csv', index=False)
        print(f"\n Saved: paper_table1_significant_improvements.csv")
    else:
        print(" No significant ensemble improvements found.")
    
    # Table 2: Summary with Mean ± Std for Paper (from summary files)
    print("\n\n TABLE 2: SUMMARY RESULTS (Mean ± Std across seeds)")
    print("-"*80)
    
    if summary_results:
        # Combine all summary data
        all_summaries = []
        for dataset_name, summary_df in summary_results.items():
            summary_df['Dataset'] = dataset_name
            all_summaries.append(summary_df)
        
        if all_summaries:
            combined_summary = pd.concat(all_summaries, ignore_index=True)
            
            # Format for paper presentation
            paper_table2 = combined_summary[[
                'Dataset', 'Model', 'Type', 'Model1', 'Model2',
                'Image_AP_AUPR_mean', 'Image_AP_AUPR_std',
                'AUsPRO@0.05_mean', 'AUsPRO@0.05_std',
                'TPR@TNR0.95_mean', 'TPR@TNR0.95_std'
            ]].round(4)
            
            print(paper_table2.to_string(index=False))
            
            # Save for LaTeX
            paper_table2.to_csv('paper_table2_summary_with_std.csv', index=False)
            print(f"\n Saved: paper_table2_summary_with_std.csv")
            
            # Generate LaTeX-friendly format
            latex_table = []
            for _, row in paper_table2.iterrows():
                ap_mean = row['Image_AP_AUPR_mean']
                ap_std = row['Image_AP_AUPR_std']
                auspro_mean = row['AUsPRO@0.05_mean']
                auspro_std = row['AUsPRO@0.05_std']
                tpr95_mean = row['TPR@TNR0.95_mean']
                tpr95_std = row['TPR@TNR0.95_std']
                
                latex_table.append({
                    'Dataset': row['Dataset'],
                    'Model': row['Model'],
                    'Type': row['Type'],
                    'AP': f"{ap_mean:.3f}±{ap_std:.3f}",
                    'AUsPRO': f"{auspro_mean:.3f}±{auspro_std:.3f}",
                    'TPR@95': f"{tpr95_mean:.3f}±{tpr95_std:.3f}"
                })
            
            latex_df = pd.DataFrame(latex_table)
            latex_df.to_csv('paper_table2_latex_format.csv', index=False)
            print(f" Saved: paper_table2_latex_format.csv (LaTeX ready)")
        
    # Table 3: Best Ensemble per Dataset  
    print("\n\n TABLE 3: BEST ENSEMBLE PER DATASET")
    print("-"*80)
    
    if len(significant_improvements) > 0:
        best_per_dataset = significant_improvements.loc[
            significant_improvements.groupby('Dataset')['AP_Improv_Mean'].idxmax()
        ]
        
        best_table = best_per_dataset[[
            'Dataset', 'Method', 'Model1', 'Model2', 
            'AP_Improv_Mean', 'sPRO_Improv_Mean', 'AUsPRO_Improv_Mean'
        ]].round(4)
        
        print(best_table.to_string(index=False))
        best_table.to_csv('paper_table3_best_per_dataset.csv', index=False)
        print(f"\n Saved: paper_table3_best_per_dataset.csv")
    
    # Summary Statistics
    print("\n\n SUMMARY STATISTICS")
    print("-"*50)
    
    total_datasets = improvements_df['Dataset'].nunique()
    total_ensembles = len(improvements_df)
    significant_ensembles = len(significant_improvements)
    
    print(f" Total Datasets Analyzed: {total_datasets}")
    print(f" Total Ensemble Experiments: {total_ensembles}")
    print(f" Significant Improvements: {significant_ensembles}")
    
    if len(significant_improvements) > 0:
        mean_ap_imp = significant_improvements['AP_Improv_Mean'].mean()
        mean_spro_imp = significant_improvements['sPRO_Improv_Mean'].mean()
        print(f" Average AP Improvement: {mean_ap_imp:.4f} ({mean_ap_imp*100:.2f}%)")
        print(f" Average sPRO Improvement: {mean_spro_imp:.4f} ({mean_spro_imp*100:.2f}%)")
        
        # Best performing ensemble overall
        best_overall = significant_improvements.loc[significant_improvements['AP_Improv_Mean'].idxmax()]
        print(f"\n BEST OVERALL ENSEMBLE:")
        print(f"Dataset: {best_overall['Dataset']}")
        print(f"Method: {best_overall['Method']}")
        print(f"Models: {best_overall['Model1']} + {best_overall['Model2']}")
        print(f"AP Improvement: +{best_overall['AP_Improv_Mean']:.4f} ({best_overall['AP_Improv_Mean']*100:.2f}%)")

def generate_latex_table(df, filename, caption="", label=""):
    """Generate LaTeX table format"""
    with open(filename, 'w') as f:
        f.write("\\begin{table}[htbp]\n")
        f.write("\\centering\n")
        f.write(f"\\caption{{{caption}}}\n")
        f.write(f"\\label{{{label}}}\n")
        f.write("\\begin{tabular}{" + "c" * len(df.columns) + "}\n")
        f.write("\\toprule\n")
        
        # Headers
        f.write(" & ".join(df.columns) + " \\\\\n")
        f.write("\\midrule\n")
        
        # Data rows
        for _, row in df.iterrows():
            f.write(" & ".join([f"{val:.3f}" if isinstance(val, (int, float)) else str(val) 
                               for val in row]) + " \\\\\n")
        
        f.write("\\bottomrule\n")
        f.write("\\end{tabular}\n")
        f.write("\\end{table}\n")

def main():
    print(" ENSEMBLE RESULTS ANALYSIS FOR ACADEMIC PUBLICATION")
    print("="*60)
    print(" Loading data from ensemble_results/ directory...")
    
    # Load all results (both all_results and summary files)
    results, summary_results = load_ensemble_results()
    
    if not results and not summary_results:
        print(" No ensemble results found. Make sure ensemble_simple.py has been run.")
        print("   Expected structure: ensemble_results/{dataset}/{dataset}_all_results.csv")
        print("                      ensemble_results/{dataset}/{dataset}_summary.csv")
        return
    
    print(f" Loaded data from {len(results)} datasets")
    
    # Analyze improvements using detailed results
    if results:
        improvements_df = analyze_improvements(results)
        
        if improvements_df.empty:
            print(" No improvement data generated.")
            return
        
        print(f" Analyzed {len(improvements_df)} ensemble experiments")
        
        # Generate publication tables
        generate_paper_tables(improvements_df, summary_results)
        
        # Save complete analysis
        improvements_df.to_csv('complete_ensemble_analysis.csv', index=False)
        print(f"\n Complete analysis saved: complete_ensemble_analysis.csv")
        
    else:
        print("  No detailed results found, only summary data available.")
        
        # If only summary data, create basic paper table
        if summary_results:
            print("\n SUMMARY DATA ONLY - BASIC PAPER TABLE")
            print("-"*60)
            
            all_summaries = []
            for dataset_name, summary_df in summary_results.items():
                summary_df['Dataset'] = dataset_name
                all_summaries.append(summary_df)
            
            if all_summaries:
                combined_summary = pd.concat(all_summaries, ignore_index=True)
                
                # Format for paper presentation
                paper_table = combined_summary[[
                    'Dataset', 'Model', 'Type', 'Model1', 'Model2',
                    'Image_AP_AUPR_mean', 'Image_AP_AUPR_std',
                    'AUsPRO@0.05_mean', 'AUsPRO@0.05_std'
                ]].round(4)
                
                print(paper_table.to_string(index=False))
                paper_table.to_csv('paper_summary_only.csv', index=False)
                print(f"\n Summary table saved: paper_summary_only.csv")
    
    print(f"\n Analysis complete! Check the generated CSV files for publication-ready tables.")
    print("\n Generated files:")
    print("    paper_table1_significant_improvements.csv  - Ensembles with improvements")
    print("    paper_table2_summary_with_std.csv          - Mean ± Std for all models")
    print("    paper_table2_latex_format.csv              - LaTeX-ready format")
    print("    paper_table3_best_per_dataset.csv          - Best ensemble per dataset")
    print("    complete_ensemble_analysis.csv             - Full analysis data")

if __name__ == "__main__":
    main()
